using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;

namespace CryptoProxy.Services
{
    public class NonceState
    {
        public byte[] Nonce { get; set; }
        public DateTime Created { get; set; }
        public int UseCount { get; set; }
        public bool Invalidated { get; set; }
    }

    public class CryptoSessionManager
    {
        private readonly Dictionary<string, NonceState> _activeSessions = new();
        private readonly ReaderWriterLockSlim _sessionLock = new();
        private readonly byte[] _masterKey;

        public CryptoSessionManager(byte[] masterKey)
        {
            _masterKey = masterKey;
        }

        public string InitiateSession(string clientId)
        {
            var nonce = new byte[12];
            RandomNumberGenerator.Fill(nonce);
            var sessionId = Convert.ToBase64String(
                SHA256.HashData(Encoding.UTF8.GetBytes(clientId + DateTime.UtcNow.Ticks)));

            _sessionLock.EnterWriteLock();
            try
            {
                _activeSessions[sessionId] = new NonceState
                {
                    Nonce = nonce,
                    Created = DateTime.UtcNow,
                    UseCount = 0,
                    Invalidated = false
                };
            }
            finally
            {
                _sessionLock.ExitWriteLock();
            }
            return sessionId;
        }

        public (byte[] ciphertext, byte[] tag) EncryptPayload(string sessionId, byte[] plaintext)
        {
            NonceState state = GetSessionState(sessionId);
            if (state == null)
                throw new InvalidOperationException("Session not found");

            ValidateAndAdvanceNonce(state);

            using var aesGcm = new AesGcm(_masterKey, 16);
            var ciphertext = new byte[plaintext.Length];
            var tag = new byte[16];

            aesGcm.Encrypt(state.Nonce, plaintext, ciphertext, tag);
            return (ciphertext, tag);
        }

        private NonceState GetSessionState(string sessionId)
        {
            _sessionLock.EnterReadLock();
            try
            {
                return _activeSessions.TryGetValue(sessionId, out var state) ? state : null;
            }
            finally
            {
                _sessionLock.ExitReadLock();
            }
        }

        private void ValidateAndAdvanceNonce(NonceState state)
        {
            if (state.Invalidated)
                throw new CryptographicException("Session invalidated");

            if (state.UseCount >= 1000)
            {
                state.Invalidated = true;
                throw new CryptographicException("Nonce limit reached");
            }

            state.UseCount++;
            IncrementNonce(state.Nonce);
        }

        private void IncrementNonce(byte[] nonce)
        {
            for (int i = nonce.Length - 1; i >= 0; i--)
            {
                if (++nonce[i] != 0) break;
            }
        }

        public void InvalidateSession(string sessionId)
        {
            _sessionLock.EnterWriteLock();
            try
            {
                if (_activeSessions.TryGetValue(sessionId, out var state))
                {
                    state.Invalidated = true;
                    CryptographicOperations.ZeroMemory(state.Nonce);
                    _activeSessions.Remove(sessionId);
                }
            }
            finally
            {
                _sessionLock.ExitWriteLock();
            }
        }
    }

    [ApiController]
    [Route("api/crypto")]
    public class CryptoController : ControllerBase
    {
        private readonly CryptoSessionManager _manager;

        public CryptoController(CryptoSessionManager manager)
        {
            _manager = manager;
        }

        [HttpPost("encrypt")]
        public IActionResult Encrypt([FromHeader(Name = "X-Session-Id")] string sessionId,
                                     [FromBody] byte[] payload)
        {
            if (string.IsNullOrEmpty(sessionId) || payload == null || payload.Length == 0)
                return BadRequest();

            try
            {
                var (ciphertext, tag) = _manager.EncryptPayload(sessionId, payload);
                return Ok(new { ciphertext = Convert.ToBase64String(ciphertext),
                               tag = Convert.ToBase64String(tag) });
            }
            catch (CryptographicException ex)
            {
                return StatusCode(403, ex.Message);
            }
        }
    }
}
